/**
 * Locks a member out without removing them: they keep their membership, role
 * and seat, and cannot act until reinstated. Suspending an owner is subject to
 * the same last-owner rule as removal, counting only owners not suspended.
 */
export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await loadTargetMember(actor, input);

  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Lifts a suspension. Reinstating an active member is a no-op. */
export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await loadTargetMember(actor, input);

  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * Refuses new work for a suspended assignee. Called by the issue service before
 * it writes an assignment; un-assigning (a null assignee) never reaches here.
 */
export async function assertCanReceiveWork(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member?.status === "suspended") {
    throw new MemberSuspendedError(userId);
  }
}

