import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe, resetEventBus } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as commentService from "@/server/services/comment-service";
import * as notificationService from "@/server/services/notification-service";
import { buildDigest } from "@/server/services/digest-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { commentInput } from "../helpers/factories";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch: suspension", () => {
  it("runs the whole flow", async () => {
    const t = await createTenant("scratch-susp", "growth");
    const admin = await memberRepo.findMember(t.org.id, t.userIds.admin);
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    const owner = await memberRepo.findMember(t.org.id, t.userIds.owner);
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (!admin || !viewer || !owner || !member) throw new Error("fixtures");

    const published: string[] = [];
    const offs = [
      subscribe("member.suspended", () => { published.push("suspended"); }),
      subscribe("member.reinstated", () => { published.push("reinstated"); }),
    ];

    // Owner cannot be suspended by admin; self refused; admin can suspend a viewer.
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: admin.id })).rejects.toThrow();

    const before = await usageRepo.getUsage(t.org.id);
    const s = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(s.status).toBe("suspended");
    expect(published).toEqual(["suspended"]);
    // Idempotent: no second publish.
    const again = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(again.status).toBe("suspended");
    expect(published).toEqual(["suspended"]);

    // Seats unchanged.
    const after = await usageRepo.getUsage(t.org.id);
    expect(after.seatsUsed).toBe(before.seatsUsed);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(before.seatsUsed);

    // Cannot act.
    expect(await resolveActorForOrg({ userId: t.userIds.viewer, email: "x", activeOrgId: null, expiresAt: new Date().toISOString() } as never, t.org.slug)).toBeNull();

    // Cannot be assigned new work.
    await expect(
      issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Assign to viewer", assigneeId: t.userIds.viewer })),
    ).rejects.toThrow(/suspended/);

    // Mentions drop them.
    const c = await commentService.createComment(t.actors.member, commentInput(t.org.id, t.issue.id, { body: "hi @" + (await memberRepo.listMembers({ orgId: t.org.id, limit: 100, cursor: null })).items.find((m) => m.userId === t.userIds.viewer)!.user.email.split("@")[0], mentionedUserIds: [t.userIds.viewer] } as never));
    expect(c.mentionedUserIds ?? []).not.toContain(t.userIds.viewer);

    // Direct notify is dropped.
    const rows = await notificationService.notify(t.org.id, "comment_mention", [t.userIds.viewer], { title: "t", body: "b", href: "/", actorId: null });
    expect(rows).toHaveLength(0);

    // Workspace not listed.
    const { listOrganizationsForUser } = await import("@/server/services/organization-service");
    expect((await listOrganizationsForUser(t.userIds.viewer)).map((o) => o.id)).not.toContain(t.org.id);

    // Reinstate.
    const r = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(r.status).toBe("active");
    expect(published).toEqual(["suspended", "reinstated"]);
    const noop = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(noop.status).toBe("active");
    expect(published).toEqual(["suspended", "reinstated"]);

    // Audit log has both rows.
    const feed = await activityRepo.listActivity({ orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null } as never);
    expect(feed.items.map((e) => e.action).sort()).toEqual(["member.reinstated", "member.suspended"]);

    // Last owner: suspend the only owner refused.
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow(/at least one owner/);

    // Removed member is not found for suspend.
    await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: member.id });
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: member.id })).rejects.toThrow(/not found/i);

    offs.forEach((off) => off());
    void orgRepo; void buildDigest; void resetEventBus;
  });
});

